import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N,
    int IC,
    int IH,
    int IW,
    int OC,
    int OH,
    int OW,
    int KH,
    int KW,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w,
    int use_shared
) {
    constexpr int BW = 32;
    constexpr int BH = 16;
    constexpr int TX = 16;
    constexpr int TY = 8;
    constexpr int IC_TILE = 4;
    constexpr int OC_TILE = 4;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * TX + tx;
    const int threads = TX * TY;
    const int oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
    const int n = blockIdx.z / oc_tiles;
    const int oc_base = (blockIdx.z % oc_tiles) * OC_TILE;
    const int ow0 = blockIdx.x * BW + tx * 2;
    const int oh0 = blockIdx.y * BH + ty * 2;
    const bool valid_n = n < N;
    const int effective_h = (KH - 1) * dil_h + 1;
    const int effective_w = (KW - 1) * dil_w + 1;
    const int tile_h = (BH - 1) * stride_h + effective_h;
    const int tile_w = (BW - 1) * stride_w + effective_w;
    const int ih_base = blockIdx.y * BH * stride_h - pad_h;
    const int iw_base = blockIdx.x * BW * stride_w - pad_w;
    const int input_tile_elems = IC_TILE * tile_h * tile_w;
    const int weight_tile_elems = OC_TILE * IC_TILE * KH * KW;
    float acc[OC_TILE][4];
    #pragma unroll
    for (int o = 0; o < OC_TILE; ++o) {
        const int oc = oc_base + o;
        const float b = (bias != nullptr && valid_n && oc < OC) ? bias[oc] : 0.0f;
        acc[o][0] = b;
        acc[o][1] = b;
        acc[o][2] = b;
        acc[o][3] = b;
    }
    extern __shared__ float smem[];
    float* smem_x = smem;
    float* smem_w = smem + input_tile_elems;
    if (use_shared) {
        for (int ic0 = 0; ic0 < IC; ic0 += IC_TILE) {
            for (int idx = tid; idx < input_tile_elems; idx += threads) {
                const int iw_local = idx % tile_w;
                const int tmp = idx / tile_w;
                const int ih_local = tmp % tile_h;
                const int ic_local = tmp / tile_h;
                const int ic = ic0 + ic_local;
                const int ih = ih_base + ih_local;
                const int iw = iw_base + iw_local;
                float value = 0.0f;
                if (valid_n && ic < IC && ih >= 0 && ih < IH && iw >= 0 && iw < IW) {
                    value = x[((n * IC + ic) * IH + ih) * IW + iw];
                }
                smem_x[idx] = value;
            }
            for (int idx = tid; idx < weight_tile_elems; idx += threads) {
                const int kwkh = KH * KW;
                const int ic_span = IC_TILE * kwkh;
                const int oc_local = idx / ic_span;
                const int rem0 = idx % ic_span;
                const int ic_local = rem0 / kwkh;
                const int rem1 = rem0 % kwkh;
                const int kh = rem1 / KW;
                const int kw = rem1 % KW;
                const int oc = oc_base + oc_local;
                const int ic = ic0 + ic_local;
                float value = 0.0f;
                if (oc < OC && ic < IC) {
                    value = weight[((oc * IC + ic) * KH + kh) * KW + kw];
                }
                smem_w[idx] = value;
            }
            __syncthreads();
            if (valid_n) {
                const int channels = min(IC_TILE, IC - ic0);
                #pragma unroll
                for (int o = 0; o < OC_TILE; ++o) {
                    const int oc = oc_base + o;
                    if (oc < OC) {
                        for (int ic_local = 0; ic_local < channels; ++ic_local) {
                            for (int kh = 0; kh < KH; ++kh) {
                                const int ih00 = ty * 2 * stride_h + kh * dil_h;
                                const int ih10 = (ty * 2 + 1) * stride_h + kh * dil_h;
                                for (int kw = 0; kw < KW; ++kw) {
                                    const int iw00 = tx * 2 * stride_w + kw * dil_w;
                                    const int iw01 = (tx * 2 + 1) * stride_w + kw * dil_w;
                                    const int widx = (((o * IC_TILE + ic_local) * KH + kh) * KW + kw);
                                    const float w = smem_w[widx];
                                    acc[o][0] += smem_x[(ic_local * tile_h + ih00) * tile_w + iw00] * w;
                                    acc[o][1] += smem_x[(ic_local * tile_h + ih00) * tile_w + iw01] * w;
                                    acc[o][2] += smem_x[(ic_local * tile_h + ih10) * tile_w + iw00] * w;
                                    acc[o][3] += smem_x[(ic_local * tile_h + ih10) * tile_w + iw01] * w;
                                }
                            }
                        }
                    }
                }
            }
            __syncthreads();
        }
    } else if (valid_n) {
        for (int o = 0; o < OC_TILE; ++o) {
            const int oc = oc_base + o;
            if (oc < OC) {
                for (int ic = 0; ic < IC; ++ic) {
                    for (int kh = 0; kh < KH; ++kh) {
                        const int ih00 = ih_base + ty * 2 * stride_h + kh * dil_h;
                        const int ih10 = ih_base + (ty * 2 + 1) * stride_h + kh * dil_h;
                        for (int kw = 0; kw < KW; ++kw) {
                            const int iw00 = iw_base + tx * 2 * stride_w + kw * dil_w;
                            const int iw01 = iw_base + (tx * 2 + 1) * stride_w + kw * dil_w;
                            const float w = weight[((oc * IC + ic) * KH + kh) * KW + kw];
                            float v00 = 0.0f;
                            float v01 = 0.0f;
                            float v10 = 0.0f;
                            float v11 = 0.0f;
                            if (ih00 >= 0 && ih00 < IH && iw00 >= 0 && iw00 < IW) v00 = x[((n * IC + ic) * IH + ih00) * IW + iw00];
                            if (ih00 >= 0 && ih00 < IH && iw01 >= 0 && iw01 < IW) v01 = x[((n * IC + ic) * IH + ih00) * IW + iw01];
                            if (ih10 >= 0 && ih10 < IH && iw00 >= 0 && iw00 < IW) v10 = x[((n * IC + ic) * IH + ih10) * IW + iw00];
                            if (ih10 >= 0 && ih10 < IH && iw01 >= 0 && iw01 < IW) v11 = x[((n * IC + ic) * IH + ih10) * IW + iw01];
                            acc[o][0] += v00 * w;
                            acc[o][1] += v01 * w;
                            acc[o][2] += v10 * w;
                            acc[o][3] += v11 * w;
                        }
                    }
                }
            }
        }
    }
    if (valid_n) {
        #pragma unroll
        for (int o = 0; o < OC_TILE; ++o) {
            const int oc = oc_base + o;
            if (oc < OC) {
                float* dst = out + ((n * OC + oc) * OH * OW);
                if (oh0 < OH && ow0 < OW) dst[oh0 * OW + ow0] = acc[o][0];
                if (oh0 < OH && ow0 + 1 < OW) dst[oh0 * OW + ow0 + 1] = acc[o][1];
                if (oh0 + 1 < OH && ow0 < OW) dst[(oh0 + 1) * OW + ow0] = acc[o][2];
                if (oh0 + 1 < OH && ow0 + 1 < OW) dst[(oh0 + 1) * OW + ow0 + 1] = acc[o][3];
            }
        }
    }
}
torch::Tensor conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w
) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(x.dim() == 4, "input must have shape NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must have shape OIHW");
    TORCH_CHECK(x.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    const auto N = static_cast<int>(x.size(0));
    const auto IC = static_cast<int>(x.size(1));
    const auto IH = static_cast<int>(x.size(2));
    const auto IW = static_cast<int>(x.size(3));

    const auto OC = static_cast<int>(weight.size(0));
    const auto WIC = static_cast<int>(weight.size(1));
    const auto KH = static_cast<int>(weight.size(2));
    const auto KW = static_cast<int>(weight.size(3));

    TORCH_CHECK(IC == WIC, "input and weight channel dimensions must match");

    if (bias.has_value()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->dim() == 1 && bias->size(0) == OC, "invalid bias shape");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
    }

    const int effective_h = (KH - 1) * static_cast<int>(dil_h) + 1;
    const int effective_w = (KW - 1) * static_cast<int>(dil_w) + 1;

    const int OH =
        (IH + 2 * static_cast<int>(pad_h) -
         effective_h) / static_cast<int>(stride_h) + 1;
    const int OW =
        (IW + 2 * static_cast<int>(pad_w) -
         effective_w) / static_cast<int>(stride_w) + 1;

    TORCH_CHECK(OH >= 0 && OW >= 0, "invalid convolution output dimensions");

    auto out = torch::empty(
        {N, OC, OH, OW},
        x.options()
    );

    constexpr int BW = 32;
    constexpr int BH = 16;
    constexpr int TX = 16;
    constexpr int TY = 8;
    constexpr int IC_TILE = 4;
    const int tile_h = (BH - 1) * static_cast<int>(stride_h) + effective_h;
    const int tile_w = (BW - 1) * static_cast<int>(stride_w) + effective_w;
    constexpr int OC_TILE = 4;
    const size_t input_tile_elems = static_cast<size_t>(IC_TILE) * tile_h * tile_w;
    const size_t weight_tile_elems = static_cast<size_t>(OC_TILE) * IC_TILE * KH * KW;
    const size_t shared_bytes = (input_tile_elems + weight_tile_elems) * sizeof(float);
    const size_t shared_limit = 48 * 1024;
    const int use_shared = shared_bytes <= shared_limit ? 1 : 0;
    dim3 grid(
        (OW + BW - 1) / BW,
        (OH + BH - 1) / BH,
        N * ((OC + OC_TILE - 1) / OC_TILE)
    );
    dim3 block(TX, TY, 1);

    const float* bias_ptr = nullptr;
    if (bias.has_value()) {
        bias_ptr = bias->data_ptr<float>();
    }

    auto stream = at::cuda::getCurrentCUDAStream(x.device().index()).stream();

    conv2d_kernel<<<
        grid,
        block,
        use_shared ? shared_bytes : 0,
        stream
    >>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        out.data_ptr<float>(),
        N,
        IC,
        IH,
        IW,
        OC,
        OH,
        OW,
        KH,
        KW,
        static_cast<int>(stride_h),
        static_cast<int>(stride_w),
        static_cast<int>(pad_h),
        static_cast<int>(pad_w),
        static_cast<int>(dil_h),
        static_cast<int>(dil_w),
        use_shared
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d", &conv2d_cuda, "Custom CUDA 2D convolution");
}
"""

_conv2d_ext = load_inline(
    name="custom_conv2d_cuda_ext",
    cpp_sources="",
    cuda_sources=_cuda_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        bias: bool = False,
    ):
        super().__init__()

        self.conv2d = nn.Conv2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv2d_ext.conv2d(
            x.contiguous(),
            self.conv2d.weight.contiguous(),
            self.conv2d.bias.contiguous() if self.conv2d.bias is not None else None,
            self.conv2d.stride[0],
            self.conv2d.stride[1],
            self.conv2d.padding[0],
            self.conv2d.padding[1],
            self.conv2d.dilation[0],
            self.conv2d.dilation[1],
        )

